def generate_layout(layout_type, **kwargs):
    if layout_type == 'center':
        return {
            'display': 'flex',
            'justify-content': 'center',
            'align-items': 'center',
            'min-height': '100vh'
        }

    elif layout_type == 'navbar':
        return {
            'display': 'flex',
            'justify-content': 'space-between',
            'align-items': 'center',
            'padding': '0 24px',
            'height': '64px'
        }

    elif layout_type == 'card-grid':
        min_width = kwargs.get('min_width', '250px')
        gap = kwargs.get('gap', '16px')
        return {
            'display': 'grid',
            'grid-template-columns': f'repeat(auto-fit, minmax({min_width}, 1fr))',
            'gap': gap
        }

    elif layout_type == 'sidebar-layout':
        sidebar_width = kwargs.get('sidebar_width', '250px')
        gap = kwargs.get('gap', '24px')
        return {
            'display': 'flex',
            'gap': gap,
            'sidebar': {
                'flex': f'0 0 {sidebar_width}'
            },
            'content': {
                'flex': '1'
            }
        }

    elif layout_type == 'holy-grail':
        return {
            'display': 'grid',
            'grid-template-areas': '"header header" "sidebar content" "footer footer"',
            'grid-template-columns': '250px 1fr',
            'grid-template-rows': 'auto 1fr auto',
            'min-height': '100vh',
            'gap': '0'
        }

    else:
        raise ValueError(f"Bilinmeyen layout tipi: {layout_type}")

