function generateLayout(layoutType, options = {}) {
    switch (layoutType) {
        case 'center':
            return {
                display: 'flex',
                'justify-content': 'center',
                'align-items': 'center',
                'min-height': '100vh'
            };

        case 'navbar':
            return {
                display: 'flex',
                'justify-content': 'space-between',
                'align-items': 'center',
                padding: '0 24px',
                height: '64px'
            };

        case 'card-grid': {
            const minWidth = options.minWidth || '250px';
            const gap = options.gap || '16px';
            return {
                display: 'grid',
                'grid-template-columns': `repeat(auto-fit, minmax(${minWidth}, 1fr))`,
                gap: gap
            };
        }

        case 'sidebar-layout': {
            const sidebarWidth = options.sidebarWidth || '250px';
            const sGap = options.gap || '24px';
            return {
                display: 'flex',
                gap: sGap,
                sidebar: {
                    flex: `0 0 ${sidebarWidth}`
                },
                content: {
                    flex: '1'
                }
            };
        }

        case 'holy-grail':
            return {
                display: 'grid',
                'grid-template-areas': '"header header" "sidebar content" "footer footer"',
                'grid-template-columns': '250px 1fr',
                'grid-template-rows': 'auto 1fr auto',
                'min-height': '100vh',
                gap: '0'
            };

        default:
            throw new Error(`Bilinmeyen layout tipi: ${layoutType}`);
    }
}
